"use client";

import React, { useState } from "react";
import { Wifi, RefreshCw } from "lucide-react";

export function MobileOfflineSyncStatus() {
  const [synced, setSynced] = useState(true);

  return (
    <div className="w-full max-w-sm bg-card/45 backdrop-blur-xl border border-border/50 p-4 rounded-xl shadow-lg select-none font-sans text-foreground">
      <div className="flex items-center justify-between gap-3">
        <div className="flex items-center gap-2">
          <Wifi className={`w-4 h-4 ${synced ? "text-emerald-400" : "text-amber-400 animate-pulse"}`} />
          <div className="text-xs">
            <p className="font-bold leading-none">{synced ? "Cloud Sync Active" : "Pending Offline Sync"}</p>
            <p className="text-[10px] text-muted-foreground/60">{synced ? "All operational changes synced." : "3 assets waiting queue upload."}</p>
          </div>
        </div>

        <button 
          onClick={() => setSynced(!synced)}
          className="p-1.5 bg-secondary/30 hover:bg-secondary/60 rounded-lg text-muted-foreground transition-all"
        >
          <RefreshCw className="w-3.5 h-3.5" />
        </button>
      </div>
    </div>
  );
}
